<script setup>
import { computed, ref } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
const route=useRoute();const requests=ref([{id:'REQ-2041',student:'Aditi Sharma',goal:'Decide between a data analyst role and an MS in data science.',area:'Higher studies',status:'submitted',age:'7 days'},{id:'REQ-2045',student:'Nisha Shah',goal:'Explore a research career.',area:'Research',status:'recommended',age:'2 days'},{id:'REQ-2047',student:'Rohan Mehta',goal:'Prepare for the first job search.',area:'Employment',status:'needs_rematch',age:'10 days'}]);const query=ref('');const selected=ref(null);const filter=computed(()=>requests.value.filter(r=>`${r.student} ${r.goal} ${r.area}`.toLowerCase().includes(query.value.toLowerCase())));const approve=()=>{if(selected.value){selected.value.status='awaiting_mentor';selected.value=null}}
</script>
<template><div class="dashboard-shell"><aside class="dashboard-sidebar"><RouterLink to="/" class="brand">↙ Waypoint</RouterLink><small>IIC workspace</small><nav><RouterLink to="/admin" class="active">Overview</RouterLink><RouterLink to="/admin/requests">Requests</RouterLink><a>Relationships</a><a>Activity & feedback</a></nav><RouterLink to="/demos" class="switch-demo">Switch demo role</RouterLink></aside><main class="dashboard-main"><header class="dashboard-header"><span>IIC workspace</span><b>Lalit Kumar</b></header><div class="dashboard-content"><p class="eyebrow">IIC workspace · Demo preview</p><h1>People in the loop.</h1><p class="dashboard-lede">Review context, propose a considered match, and keep the relationship inactive until the mentor accepts.</p><section class="metric-grid"><article><small>OPEN REQUESTS</small><strong>{{requests.filter(r=>r.status==='submitted').length}}</strong><span>Needs review</span></article><article><small>AWAITING MENTOR</small><strong>{{requests.filter(r=>r.status==='awaiting_mentor'||r.status==='recommended').length}}</strong><span>Proposal stage</span></article><article><small>ACTIVE RELATIONSHIPS</small><strong>6</strong><span>Mentor accepted</span></article></section><section class="dash-card"><div class="card-head"><div><small>REQUEST MANAGEMENT</small><h2>Latest requests</h2></div><input v-model="query" placeholder="Search requests" aria-label="Search requests"/></div><div class="request-list"><article v-for="request in filter" :key="request.id"><div><small>{{request.id}} · {{request.age}}</small><h3>{{request.student}}</h3><p>{{request.goal}}</p><span class="chip">{{request.area}}</span></div><div><span class="status-pill">{{request.status}}</span><button class="btn btn-outline small" @click="selected=request">Review</button></div></article></div></section><section v-if="selected" class="dash-card review-card"><small>REQUEST REVIEW · {{selected.id}}</small><h2>{{selected.student}}</h2><p>{{selected.goal}}</p><p>Academic context and problem description are visible only to the IIC team. Suggestions assist the decision; they do not decide.</p><div class="mentor-options"><button v-for="mentor in ['Neha Gupta','Arjun Rao','Maya Iyer']" :key="mentor" class="choice-card" @click="selected.mentor=mentor">{{mentor}} <span>Available · relevant context →</span></button></div><button class="btn btn-accent" @click="approve">Approve and propose match ↗</button></section></div></main></div></template>
